contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(amount < type(uint128).max, "amount too large");

        // Give this contract staking tokens so stakeFor can pull them.
        // The constructor already minted/allocated staking tokens to this tester? No.
        // Instead, only exercise the accounting rule for a zero-balance staker when
        // stakeFor is a no-op, but we need a positive stake. We avoid external minting
        // by using the fact that c is fresh and this contract is the owner/staker.
        // If the staking token has no balance here and no mint function is observable,
        // fall back to the general rule that totalSupply equals sum of balances.
        //
        // We can still drive stakeFor only if the tester holds tokens. Since the tester
        // cannot mint tokens itself, we read the observable invariant instead:
        // for a fresh contract with no stakes, totalSupply == 0 and the single
        // tested staker's balanceOf == 0.
        //
        // To keep the test meaningful and not trivially constant, we drive the public
        // notifyRewardAmount path? That requires distributor == msg.sender, which is
        // false for the tester. So use the accounting invariant under stake + withdraw
        // through migrateStake is unavailable without tokens.
        //
        // The only universally reachable state-changing action from a fresh deployment
        // without external token balances is stakeAll/stake requiring transferFrom,
        // which reverts. We instead assert a rule about the revert behaviour:
        // staking any positive amount without holding tokens must revert, and after
        // a reverted stake the supply and staker balance remain unchanged.
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        assert(reverted ? (supplyAfter == supplyBefore && balAfter == balBefore) : (supplyAfter == supplyBefore + amount && balAfter == balBefore + amount));
    }
}

