contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount1, uint256 amount2) public {
        // Need positive amounts and a staking token that already trusts the test contract.
        require(amount1 > 0 && amount2 > 0, "amounts must be positive");

        uint256 balBefore1 = c.balanceOf(address(this));
        uint256 totalBefore1 = c.totalSupply();

        c.stakeFor(address(this), amount1);

        uint256 balAfter1 = c.balanceOf(address(this));
        uint256 totalAfter1 = c.totalSupply();

        require(balAfter1 >= balBefore1 && totalAfter1 >= totalBefore1, "no overflow");
        assert(balAfter1 - balBefore1 == amount1 && totalAfter1 - totalBefore1 == amount1);

        c.stakeFor(address(this), amount2);

        uint256 balAfter2 = c.balanceOf(address(this));
        uint256 totalAfter2 = c.totalSupply();

        require(balAfter2 >= balAfter1 && totalAfter2 >= totalAfter1, "no overflow");
        assert(balAfter2 - balAfter1 == amount2 && totalAfter2 - totalAfter1 == amount2);
    }
}

