contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        require(stakeAmount > 0);
        require(withdrawAmount > 0);
        require(withdrawAmount <= stakeAmount);

        address token = address(c.stakingToken());
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), stakeAmount)
        );
        require(ok, "mint failed");

        (ok, data) = token.call(
            abi.encodeWithSignature("approve(address,uint256)", address(c), stakeAmount)
        );
        require(ok, "approve c failed");

        c.stake(stakeAmount);

        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        require(supplyBefore >= stakeAmount);
        require(balBefore == stakeAmount);

        c.withdraw(withdrawAmount, false);

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        assert(
            supplyBefore - supplyAfter == withdrawAmount &&
            balBefore - balAfter == withdrawAmount &&
            c.totalSupply() + withdrawAmount == supplyBefore &&
            c.balanceOf(address(this)) + withdrawAmount == balBefore
        );
    }

    receive() external payable {}
}

