        require(stakeAmount > 0 && withdrawAmount > 0, "params");
        require(withdrawAmount <= stakeAmount, "withdraw too big");
        require(address(this).balance >= stakeAmount, "balance");

        // fund staking token to this contract? The token is external and we cannot mint it.
        // We must call stakeFor only if we hold stakingToken.
        // We can instead test the totalSupply/balance consistency induced by withdrawAll on a zero balance? No.
        // Use a token we hold? The staking token exists in the compilation unit but we cannot deploy it.
        // Safe route: use balanceOf and totalSupply invariants after a zero-effect path.
        // withdrawAll(claim) with zero balance reverts due to amount > 0 require inside _withdrawFor.
        uint256 userBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        bool reverted;
        try c.withdrawAll(false) { reverted = false; } catch { reverted = true; }

        uint256 userAfter = c.balanceOf(address(this));
        uint256 totalAfter = c.totalSupply();

        // Rule: a failed withdrawAll leaves both the user's balance and totalSupply unchanged.
        assert(reverted && userAfter == userBefore && totalAfter == totalBefore);
    }

    receive() external payable {}
}

