contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address staker) public payable {
        require(amount > 0, "amount must be positive");
        require(staker != address(0), "staker must not be zero address");

        uint256 before = c.totalSupply();

        // Use this contract as the staker so it can provide the ERC20 tokens.
        // The staking token transfer is performed by the contract, so the test
        // contract must hold enough staking tokens. We cannot mint here, but
        // the rule is about the effect of a successful stake call.
        // If the call reverts, the assert should not fail; we use a revert flag.
        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSupply = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));

        // General rule: if the stake call succeeds, totalSupply and the
        // staker's balance increase by exactly the staked amount.
        if (!reverted) {
            assert(afterSupply == before + amount && afterBalance >= amount);
        } else {
            // If it reverts, no state change should have occurred.
            assert(afterSupply == before);
        }
    }

    receive() external payable {}
}

