contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public {
        require(amount > 0, "amount must be positive");
        require(staker != address(0), "staker must be nonzero");

        uint256 beforeBal = c.balanceOf(staker);
        uint256 beforeSupply = c.totalSupply();

        // stakeFor transfers staking tokens from msg.sender to c.
        // The staking token is an ERC20 that a fresh deployment has no balance of;
        // if the staking token is not present or transferFrom reverts, the test
        // will revert and the rule (no revert) would be trivially true only when
        // the call succeeds. Guarding with a try/catch is not allowed for state
        // changing calls (must be top-level statements), so we assert on the
        // effect only when the call does not revert by placing the call before
        // the assertion; the checker runs one transaction and requires the assert
        // to be reached at least once, so we assume the token transfer succeeds.
        c.stakeFor(staker, amount);

        // General rule: for any staker and any positive amount, if stakeFor
        // succeeds, the staker's balance and total supply both increase by
        // exactly amount.
        assert(
            c.balanceOf(staker) == beforeBal + amount &&
            c.totalSupply() == beforeSupply + amount
        );
    }

    receive() external payable {}
}

