    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, address staker) public {
        require(stakeAmount > 0, "amount must be positive");
        require(staker != address(0), "staker must be nonzero");

        IERC20 stakingToken = IERC20(c.stakingToken());
        require(stakingToken.balanceOf(address(this)) >= stakeAmount, "test lacks staking tokens");

        uint256 beforeStakerBalance = c.balanceOf(staker);
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeContractTokenBalance = stakingToken.balanceOf(address(c));

        c.stakeFor(staker, stakeAmount);

        uint256 afterStakerBalance = c.balanceOf(staker);
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterContractTokenBalance = stakingToken.balanceOf(address(c));

        assert(
            afterStakerBalance == beforeStakerBalance + stakeAmount &&
            afterTotalSupply == beforeTotalSupply + stakeAmount &&
            afterContractTokenBalance == beforeContractTokenBalance + stakeAmount
        );
    }
}

