contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Give the test contract `amount` staking tokens to work with.
        c.stakingToken().transfer(address(this), amount);

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        // Approve and stake everything the test contract holds.
        c.stakingToken().approve(address(c), amount);
        c.stakeAll();

        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        assert(balanceAfter == balanceBefore + amount && totalSupplyAfter == totalSupplyBefore + amount);
    }

    receive() external payable {}
}

