contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeSupply = c.totalSupply();
        bool reverted;

        if (amount > 0 && c.stakingToken().balanceOf(address(this)) >= amount) {
            c.stakingToken().approve(address(c), amount);
            try c.stake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!reverted && amount > 0) {
            assert(c.balanceOf(address(this)) == beforeBalance + amount && c.totalSupply() == beforeSupply + amount);
        } else {
            assert(c.balanceOf(address(this)) == beforeBalance && c.totalSupply() == beforeSupply);
        }
    }
}

