            success = true;
        } catch {
            success = false;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(_for);

        assert(!success || (totalAfter == totalBefore + _amount && balAfter == balBefore + _amount));
    }

    receive() external payable {}
}

