contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount, bool claim) public {
        require(staker != address(0));

        // Zero-amount stake must revert; non-zero stake must succeed if tokens are available.
        bool zeroStakeReverted;
        try c.stakeFor(staker, 0) { zeroStakeReverted = false; } catch { zeroStakeReverted = true; }
        assert(zeroStakeReverted);

        // From here on, only operate with non-zero amounts.
        require(stakeAmount > 0);

        // Record the staking supply before any successful deposit.
        uint256 supplyBefore = c.totalSupply();
        require(supplyBefore == 0);

        // Successful stake increases totalSupply by exactly the staked amount.
        c.stakeFor(staker, stakeAmount);
        uint256 supplyAfterStake = c.totalSupply();
        assert(supplyAfterStake == stakeAmount);

        // The staker's balance reflects exactly the deposited amount.
        assert(c.balanceOf(staker) == stakeAmount);

        // A withdrawal exceeding the staker's balance must revert.
        bool overWithdrawReverted;
        try c.withdraw(stakeAmount + 1, false) { overWithdrawReverted = false; } catch { overWithdrawReverted = true; }
        assert(overWithdrawReverted);

        // Only test a positive withdrawal if the parameter is positive.
        require(withdrawAmount > 0);
        require(withdrawAmount <= stakeAmount);

        // Valid withdrawal reduces totalSupply and the staker's balance by the withdrawn amount.
        c.withdraw(withdrawAmount, claim);
        uint256 supplyAfterWithdraw = c.totalSupply();
        assert(supplyAfterWithdraw == stakeAmount - withdrawAmount);
        assert(c.balanceOf(staker) == stakeAmount - withdrawAmount);

        // If the entire stake is withdrawn, supply and balance become zero.
        if (withdrawAmount == stakeAmount) {
            assert(c.totalSupply() == 0);
            assert(c.balanceOf(staker) == 0);
        }
    }

    receive() external payable {}
}

