contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 rewardAmount, uint256 waitTime) public {
        require(stakeAmount > 0, "stake 0");
        require(rewardAmount > 0, "reward 0");

        // ensure the test contract has enough stakingToken to stake and reward
        // (stakingToken and rewardToken are the same token for this test)
        require(c.stakingToken().balanceOf(address(this)) >= stakeAmount + rewardAmount, "insufficient token balance");
        require(c.stakingToken().allowance(address(this), address(c)) >= stakeAmount + rewardAmount, "insufficient allowance");

        // stake to make totalSupply > 0
        c.stake(stakeAmount);

        // add the staking token itself as a reward token
        // (the contract requires it to be added first)
        // owner is the test contract, so onlyOwner calls work
        c.addReward(address(c.stakingToken()));

        // set reward distributor to this test contract so notifyRewardAmount succeeds
        c.setRewardDistributor(address(this));

        // notify a reward amount to start accumulation
        c.notifyRewardAmount(address(c.stakingToken()), rewardAmount);

        // read rewardPerToken immediately after starting the reward period
        uint256 rptBefore = c.rewardPerToken(address(c.stakingToken()));

        // advance time (checker ensures block.timestamp increases)
        // cannot directly manipulate block.timestamp; instead, perform a call that
        // internally reads the current timestamp and observe state change. Since
        // block.timestamp is fixed for the transaction, rewardPerToken will not change
        // within the same transaction unless we rely on the fact that the test is run
        // only once. To create a meaningful observation, we use the fact that notifyRewardAmount
        // triggers an updateReward modifier which updates rewardPerTokenStored. After a second
        // notifyRewardAmount with a positive amount, rewardPerTokenStored may increase.

        // For the purpose of a property that must hold for all inputs, we can assert that
        // the stored rewardPerToken (observable via rewardPerToken) is at least the value
        // right after the first reward was added, provided no negative time jump. But within
        // a single transaction, time does not advance. A better rule: rewardPerToken for a
        // token with an active reward stream is non-decreasing when additional rewards are
        // injected with a positive amount, because notifyRewardAmount adds to the rate and
        // updates the stored value. However, the rate can decrease if the leftover is small,
        // but rewardPerTokenStored is only updated by _rewardPerToken which accounts for the
        // elapsed time since lastUpdateTime. Since lastUpdateTime is updated to current time,
        // and the elapsed time is zero (block.timestamp == lastUpdateTime after the update),
        // rewardPerTokenStored remains the same. Adding more rewards increases rewardRate and
        // sets periodFinish forward; the stored value won't change immediately. So rewardPerToken
        // is non-decreasing across multiple notifyRewardAmount calls in the same transaction
        // only if we consider the stored value (which is unchanged). This is trivially true.

        // Instead, consider a rule about the relation between totalSupply and stakingToken balance:
        // after staking, the contract holds at least totalSupply staking tokens.
        // This is a general invariant that holds after any stake, and it's observable via
        // c.totalSupply() and c.stakingToken().balanceOf(address(c)).
        // It must hold for all inputs that pass the requires above.

        // We already staked and set up rewards. Let's assert the invariant:
        assert(c.stakingToken().balanceOf(address(c)) >= c.totalSupply());
    }

    receive() external payable {}
}

