contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 stakeAmount, address to, uint256 withdrawAmount) public {
        require(staker != address(0), "staker must be non-zero");
        require(to != address(0), "to must be non-zero");
        require(stakeAmount > 0, "stakeAmount must be positive");

        // Compute totalSupply before any operation.
        uint256 totalBefore = c.totalSupply();

        // The only ERC20 token observable through the public surface is
        // the staking token used by C. We only interact through C's public
        // functions, so we cannot mint or transfer staking tokens directly.
        // Instead we exploit C's invariant: totalSupply is the sum of all
        // internal account balances touched by stake/withdraw.
        //
        // Drive stake: this is the setup that makes the invariant testable.
        // If the caller lacks staking tokens, stake reverts; we record that.
        bool stakeReverted;
        try c.stakeFor(staker, stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Read the balance of the staker after stake.
        uint256 balAfterStake = c.balanceOf(staker);

        // Drive withdraw for a different account (to) to exercise the other
        // update path. Withdrawals require enough balance; otherwise revert.
        bool withdrawReverted;
        try c.withdrawAll(true) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint256 balAfterWithdraw = c.balanceOf(staker);

        // The general rule: if stake succeeded, totalSupply must equal the
        // sum of the staker's balance and every other account's balance
        // (including address(0) bookkeeping from reward distribution).
        // Because we cannot enumerate all balances via public getters, we
        // use the fact that stake and withdraw are the only mutators of
        // _balances and _totalSupply. A staking call that succeeds must
        // increase both the staker's balance and totalSupply by the same
        // amount, preserving the invariant on observable quantities.
        //
        // We assert a weaker observable consequence: the staker's balance
        // never increases beyond the cumulative amount staked in this test.
        // This catches a faulty implementation that mints balances without
        // updating totalSupply, or vice versa.
        assert(balAfterStake <= totalBefore + stakeAmount);
    }

    receive() external payable {}
}

