contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 migrateAmount) public {
        // Early contract self-reference guard: run against a copy of c is not possible in this template,
        // so we only exercise the migration path across the two logically related contracts.
        require(stakeAmount > 0 && migrateAmount > 0 && migrateAmount <= stakeAmount, "bad params");

        // Setup: the test contract must hold reward/staking tokens.  We rely on the deployment unit/
        // test harness having transferred tokens to this contract; only safe calls are made here.
        c.addReward(address(c));

        // Stake tokens into c as the test contract, then migrate them to a fresh target.
        c.stakeFor(address(this), stakeAmount);
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        c.setMigrator(address(this));
        c.migrateWithdraw(address(this), migrateAmount);

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));

        assert(
            balanceBefore > 0 &&
            supplyAfter == supplyBefore - migrateAmount &&
            balanceAfter == balanceBefore - migrateAmount
        );
    }

    receive() external payable {}
}

